```python
import sys
import bisect

def main():
    data = sys.stdin.read().split()
    n = int(data[0])                # 读入数组长度 n
    a = list(map(int, data[1:]))    # 读入数组 a
    # 计算前缀和 s，s[0]=0, s[i]=a[0]+...+a[i-1]
    s = [0]
    for v in a:
        s.append(s[-1] + v)

    M = 998244353
    total = s[n]
    maxv = 0
    # 枚举第二段结束 y，从 2 到 n-1
    for y in range(2, n):
        T = s[y]  # 前两段和
        # 找到第一个不小于 T/2 的索引
        p = bisect.bisect_left(s, T/2, 1, y)
        # 分别尝试 p 和 p-1
        for d in (0, -1):
            x = p + d
            if 1 <= x < y:
                # 计算三段乘积
                prod = s[x] * (T - s[x]) * (total - T)
                if prod > maxv:
                    maxv = prod
    # 输出对 M 取模的结果
    print(maxv % M)

if __name__ == "__main__":
    main()
